fn bit_wise_xor(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Since the problem guarantees arr1.len() == arr2.len(),
    // we can safely zip them together.
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a ^ b)
        .collect()
}

